            fsCleaner.cleanFileSpace(100000, 50000);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void cleanFileSpace(long startPosition, long extraSpace) throws IOException {
        File file = new File("your_file_name.ext");
        FileInputStream fileIn = new FileInputStream(file);
        FileOutputStream fileOut = new FileOutputStream(file);
        RandomAccessFile raf = new RandomAccessFile(fileIn, "r");
        long fileSize = file.length();

        // Check if there's enough space for the extra bytes
        if (fileSize + extraSpace > file.length()) {
            throw new IOException("Not enough space to add extra bytes!");
        }

        // Seek to the start position
        raf.seek(startPosition);

        // Copy the contents forward, overwriting the existing data
        byte[] buffer = new byte[BUFFER_SIZE];
        int bytesRead = 0;
        while ((bytesRead = raf.read(buffer)) != -1) {
            fileOut.write(buffer, 0, bytesRead);
        }

        // Close the streams
        raf.close();
        fileOut.close();
        fileIn.close();
    }
}
```
